namespace Icod.ProcPs.Pmap;

using System.Globalization;
using System.Text;
using Icod.ProcPs.Shared;

public static class Command {
	private const int Success = 0;
	private const int Failure = 1;
	private const int MissingProcessStatus = 42;
	private static readonly Encoding Utf8 = new UTF8Encoding( false );
	private static readonly HashSet<string> CompactExtendedExcludedFields = new( StringComparer.Ordinal ) { "AnonHugePages", "KernelPageSize", "MMUPageSize", "Shared_Dirty", "Private_Dirty", "Shared_Clean", "Private_Clean" };
	private const string Usage = """

Usage:
 pmap [options] PID [PID ...]

Options:
 -x, --extended              show details
 -X                          show even more details
 -XX                         show everything the kernel provides
 -d, --device                show the device format
 -q, --quiet                 do not display header and footer
 -p, --show-path             show path in the mapping
 -k, --use-kernel-name       use names provided by kernel
 -A, --range=<low>[,<high>]  limit results to the given hexadecimal range
 -r                          ignored for SunOS compatibility
 -c, --read-rc               read the default rc (not supported in this profile)
 -C, --read-rc-from=<file>   read an rc file (not supported in this profile)
 -n, --create-rc             create the default rc (not supported in this profile)
 -N, --create-rc-to=<file>   create an rc file (not supported in this profile)
 -h, --help                  display this help and exit
 -V, --version               output version information and exit
""";
	public static int Run( string[] args, TextWriter? stdout = null, TextWriter? stderr = null ) { ArgumentNullException.ThrowIfNull(args); using var output=new MemoryStream(); using var error=new MemoryStream(); var status=RunAsync(args,stdout:output,stderr:error).GetAwaiter().GetResult(); (stdout??Console.Out).Write(Utf8.GetString(output.ToArray())); (stderr??Console.Error).Write(Utf8.GetString(error.ToArray())); return status; }
	public static async Task<int> RunAsync(string[] args,Stream? stdout=null,Stream? stderr=null,IProcProcessProvider? processProvider=null,IProcMemoryMapProvider? memoryMapProvider=null,CancellationToken cancellationToken=default){
		ArgumentNullException.ThrowIfNull(args); if(0==args.Length){await WriteAsync(stderr,NormalizeLineEndings(Usage),cancellationToken).ConfigureAwait(false);return Failure;} var options=ParseArguments(args); if(null!=options.Error){if(0<options.Error.Length)await WriteLineAsync(stderr,$"pmap: {options.Error}",cancellationToken).ConfigureAwait(false);if(options.ShowUsageOnError)await WriteAsync(stderr,NormalizeLineEndings(Usage),cancellationToken).ConfigureAwait(false);return Failure;} if(options.ShowHelp){await WriteAsync(stdout,NormalizeLineEndings(Usage),cancellationToken).ConfigureAwait(false);return Success;} if(options.ShowVersion){await WriteLineAsync(stdout,"pmap from procps-ng 4.0.6",cancellationToken).ConfigureAwait(false);return Success;} foreach(var warning in options.Warnings)await WriteLineAsync(stderr,$"pmap: {warning}",cancellationToken).ConfigureAwait(false);if(options.ConfigurationMode){await WriteLineAsync(stderr,"pmap: rc-file modes are not implemented by the Batch 61 portability profile",cancellationToken).ConfigureAwait(false);return Failure;}if(0==options.ProcessIds.Count){await WriteLineAsync(stderr,"pmap: argument missing",cancellationToken).ConfigureAwait(false);return Failure;}
		var processes=processProvider??SystemProcProcessProvider.Instance;var maps=memoryMapProvider??SystemProcMemoryMapProvider.Instance;var status=Success;foreach(var processId in options.ProcessIds){cancellationToken.ThrowIfCancellationRequested();var process=await processes.GetProcessAsync(processId,cancellationToken).ConfigureAwait(false);if(!process.HasValue){if(ProcObservationAvailability.Vanished==process.Availability||ProcObservationAvailability.Reused==process.Availability){status|=MissingProcessStatus;continue;}await WriteLineAsync(stderr,$"pmap: cannot examine PID {processId}: {Diagnostic(process)}",cancellationToken).ConfigureAwait(false);status|=Failure;continue;}await WriteLineAsync(stdout,$"{processId}:   {ProcessDescription(process.Value)}",cancellationToken).ConfigureAwait(false);var observed=await maps.ObserveAsync(process.Value,options.RequiresDetails,cancellationToken).ConfigureAwait(false);if(!observed.HasValue){await WriteLineAsync(stderr,$"pmap: cannot examine PID {processId}: {Diagnostic(observed)}",cancellationToken).ConfigureAwait(false);status|=Failure;continue;}var selected=SelectRange(observed.Value.Regions,options.RangeLow,options.RangeHigh);if(PmapMode.Extended==options.Mode)await RenderExtendedAsync(selected,options,stdout,cancellationToken).ConfigureAwait(false);else if(PmapMode.Device==options.Mode)await RenderDeviceAsync(selected,options,stdout,cancellationToken).ConfigureAwait(false);else if(PmapMode.DynamicExtended==options.Mode)await RenderDynamicExtendedAsync(selected,options,stdout,cancellationToken).ConfigureAwait(false);else await RenderBasicAsync(selected,options,stdout,cancellationToken).ConfigureAwait(false);}return status;
	}
	private static async Task RenderBasicAsync(IReadOnlyList<ProcMemoryMapRegion> regions,ParsedArguments options,Stream? stdout,CancellationToken cancellationToken){ulong totalBytes=0;foreach(var region in regions){var size=RegionSize(region.Map);totalBytes=SaturatingAdd(totalBytes,size);await WriteLineAsync(stdout,string.Format(CultureInfo.InvariantCulture,"{0:x16} {1,6}K {2} {3}",region.Map.StartAddress,size>>10,RenderMode(region.Map.Permissions),MappingName(region.Map,options)),cancellationToken).ConfigureAwait(false);}if(!options.Quiet)await WriteLineAsync(stdout,string.Format(CultureInfo.InvariantCulture," total {0,16}K",totalBytes>>10),cancellationToken).ConfigureAwait(false);}
	private static async Task RenderDeviceAsync(IReadOnlyList<ProcMemoryMapRegion> regions,ParsedArguments options,Stream? stdout,CancellationToken cancellationToken){ulong total=0,shared=0,writablePrivate=0;if(!options.Quiet)await WriteLineAsync(stdout,"Address           Kbytes Mode  Offset           Device    Mapping",cancellationToken).ConfigureAwait(false);foreach(var region in regions){var size=RegionSize(region.Map);total=SaturatingAdd(total,size);if(IsShared(region.Map.Permissions))shared=SaturatingAdd(shared,size);if(IsPrivate(region.Map.Permissions)&&IsWritable(region.Map.Permissions))writablePrivate=SaturatingAdd(writablePrivate,size);await WriteLineAsync(stdout,string.Format(CultureInfo.InvariantCulture,"{0:x16} {1,7} {2,-5} {3:x16} {4,9} {5}",region.Map.StartAddress,size>>10,RenderMode(region.Map.Permissions),region.Map.Offset,RenderDevice(region.Map.Device),MappingName(region.Map,options)),cancellationToken).ConfigureAwait(false);}if(!options.Quiet)await WriteLineAsync(stdout,$"mapped: {total>>10}K    writeable/private: {writablePrivate>>10}K    shared: {shared>>10}K",cancellationToken).ConfigureAwait(false);}
	private static async Task RenderExtendedAsync(IReadOnlyList<ProcMemoryMapRegion> regions,ParsedArguments options,Stream? stdout,CancellationToken cancellationToken){ulong totalSize=0,totalRss=0,totalDirty=0;if(!options.Quiet)await WriteLineAsync(stdout,"Address           Kbytes     RSS   Dirty Mode  Mapping",cancellationToken).ConfigureAwait(false);foreach(var region in regions){var size=RegionSize(region.Map);var rss=region.GetMetric("Rss")??0;var dirty=SaturatingAdd(region.GetMetric("Shared_Dirty")??0,region.GetMetric("Private_Dirty")??0);totalSize=SaturatingAdd(totalSize,size>>10);totalRss=SaturatingAdd(totalRss,rss);totalDirty=SaturatingAdd(totalDirty,dirty);await WriteLineAsync(stdout,string.Format(CultureInfo.InvariantCulture,"{0:x16} {1,7} {2,7} {3,7} {4,-5} {5}",region.Map.StartAddress,size>>10,rss,dirty,RenderMode(region.Map.Permissions),MappingName(region.Map,options)),cancellationToken).ConfigureAwait(false);}if(!options.Quiet){await WriteLineAsync(stdout,"---------------- ------- ------- -------",cancellationToken).ConfigureAwait(false);await WriteLineAsync(stdout,string.Format(CultureInfo.InvariantCulture,"{0,-16} {1,7} {2,7} {3,7}","total kB",totalSize,totalRss,totalDirty),cancellationToken).ConfigureAwait(false);}}
	private static async Task RenderDynamicExtendedAsync(IReadOnlyList<ProcMemoryMapRegion> regions,ParsedArguments options,Stream? stdout,CancellationToken cancellationToken){var fieldNames=new List<string>();var seen=new HashSet<string>(StringComparer.Ordinal);foreach(var region in regions)foreach(var metric in region.Metrics){if(1==options.DynamicLevel&&CompactExtendedExcludedFields.Contains(metric.Name))continue;if(seen.Add(metric.Name))fieldNames.Add(metric.Name);}var includeVmFlags=2<=options.DynamicLevel&&regions.Any(static region=>!string.IsNullOrWhiteSpace(region.VmFlags));if(!options.Quiet){var header=new StringBuilder("Address          Perm Offset           Device Inode");foreach(var field in fieldNames)header.Append(' ').Append(field);if(includeVmFlags)header.Append(" VmFlags");header.Append(" Mapping");await WriteLineAsync(stdout,header.ToString(),cancellationToken).ConfigureAwait(false);}var totals=fieldNames.ToDictionary(static field=>field,static _=>0UL,StringComparer.Ordinal);foreach(var region in regions){var line=new StringBuilder();line.AppendFormat(CultureInfo.InvariantCulture,"{0:x16} {1,-4} {2:x16} {3,-9} {4}",region.Map.StartAddress,region.Map.Permissions,region.Map.Offset,RenderDevice(region.Map.Device),region.Map.Inode);foreach(var field in fieldNames){var value=region.GetMetric(field)??0;totals[field]=SaturatingAdd(totals[field],value);line.Append(' ').Append(value.ToString(CultureInfo.InvariantCulture));}if(includeVmFlags)line.Append(' ').Append(region.VmFlags??string.Empty);line.Append(' ').Append(MappingName(region.Map,options,preserveKernelPseudoName:true));await WriteLineAsync(stdout,line.ToString(),cancellationToken).ConfigureAwait(false);}if(!options.Quiet&&0<fieldNames.Count){var footer=new StringBuilder("                 ");foreach(var field in fieldNames)footer.Append(' ').Append(totals[field].ToString(CultureInfo.InvariantCulture));footer.Append(" KB");await WriteLineAsync(stdout,footer.ToString(),cancellationToken).ConfigureAwait(false);}}
	private static IReadOnlyList<ProcMemoryMapRegion> SelectRange(IReadOnlyList<ProcMemoryMapRegion> regions,ulong low,ulong high){var selected=new List<ProcMemoryMapRegion>();foreach(var region in regions){if(0==region.Map.EndAddress)continue;if(region.Map.EndAddress-1<low)continue;if(high<region.Map.StartAddress)break;selected.Add(region);}return selected;}
	private static string ProcessDescription(ProcProcessSnapshot process){if(process.CommandLineArguments.HasValue&&0<process.CommandLineArguments.Value.Count)return string.Join(" ",process.CommandLineArguments.Value);if(process.CommandName.HasValue&&!string.IsNullOrWhiteSpace(process.CommandName.Value))return process.CommandName.Value;return $"[{process.ProcessId}]";}
	private static string MappingName(ProcMemoryMapEntry map,ParsedArguments options,bool preserveKernelPseudoName=false){var path=map.Path;if(string.IsNullOrWhiteSpace(path))return "  [ anon ]";if(path.Contains('/')){if(options.ShowPath)return path;var name=System.IO.Path.GetFileName(path);return 0==name.Length?path:name;}if(string.Equals(path,"[stack]",StringComparison.Ordinal))return "  [ stack ]";if(preserveKernelPseudoName||options.UseKernelName)return path;return "  [ anon ]";}
	private static string RenderMode(string permissions){Span<char> mode=stackalloc char[5];for(var index=0;index<4;index++)mode[index]=index<permissions.Length?permissions[index]:'-';if('p'==mode[3])mode[3]='-';mode[4]='-';return new string(mode);} private static string RenderDevice(string device){var parts=device.Split(':',2);if(2!=parts.Length||!uint.TryParse(parts[0],NumberStyles.AllowHexSpecifier,CultureInfo.InvariantCulture,out var major)||!uint.TryParse(parts[1],NumberStyles.AllowHexSpecifier,CultureInfo.InvariantCulture,out var minor))return device;return string.Format(CultureInfo.InvariantCulture,"{0:x3}:{1:x5}",major,minor);} private static bool IsPrivate(string permissions)=>3<permissions.Length&&'p'==permissions[3];private static bool IsShared(string permissions)=>3<permissions.Length&&'s'==permissions[3];private static bool IsWritable(string permissions)=>1<permissions.Length&&'w'==permissions[1];private static ulong RegionSize(ProcMemoryMapEntry map)=>map.EndAddress>=map.StartAddress?map.EndAddress-map.StartAddress:0;private static ulong SaturatingAdd(ulong left,ulong right)=>ulong.MaxValue-left<right?ulong.MaxValue:left+right;
	private static string Diagnostic<T>(ProcObservedValue<T> observation){if(!string.IsNullOrWhiteSpace(observation.Diagnostic))return observation.Diagnostic;return observation.Availability switch{ProcObservationAvailability.AccessDenied=>"Permission denied",ProcObservationAvailability.Unsupported=>"Memory maps are not supported on this platform",ProcObservationAvailability.Reused=>"Process identifier was reused",ProcObservationAvailability.Vanished=>"No such process",ProcObservationAvailability.Malformed=>"Malformed process memory-map data",_=>"Memory-map information is unavailable"};}
	private static ParsedArguments ParseArguments(string[] args){var result=new ParsedArguments();var operands=new List<string>();var endOptions=false;for(var index=0;index<args.Length;index++){var argument=args[index];if(endOptions){operands.Add(argument);continue;}if("--"==argument){endOptions=true;continue;}if(argument.StartsWith("--",StringComparison.Ordinal)){var equals=argument.IndexOf('=');var name=0<=equals?argument[..equals]:argument;var attached=0<=equals?argument[(equals+1)..]:null;switch(name){case "--extended":result.SetExclusiveMode(PmapMode.Extended);break;case "--device":result.SetExclusiveMode(PmapMode.Device);break;case "--quiet":result.Quiet=true;break;case "--show-path":result.ShowPath=true;break;case "--use-kernel-name":result.UseKernelName=true;break;case "--range":if(!TryTakeValue(args,ref index,attached,out var range)||!TryParseRange(range,out result.RangeLow,out result.RangeHigh))result.Fail($"failed to parse argument: '{range??string.Empty}'",false);break;case "--read-rc":result.SetConfigurationMode("c");break;case "--read-rc-from":if(!TryTakeValue(args,ref index,attached,out _))result.Fail("option '--read-rc-from' requires an argument");else result.SetConfigurationMode("C");break;case "--create-rc":result.SetConfigurationMode("n");break;case "--create-rc-to":if(!TryTakeValue(args,ref index,attached,out _))result.Fail("option '--create-rc-to' requires an argument");else result.SetConfigurationMode("N");break;case "--help":result.ShowHelp=true;break;case "--version":result.ShowVersion=true;break;default:result.Fail($"unrecognized option '{argument}'");break;}continue;}if(1<argument.Length&&'-'==argument[0]){for(var optionIndex=1;optionIndex<argument.Length;optionIndex++){var option=argument[optionIndex];switch(option){case 'x':result.SetExclusiveMode(PmapMode.Extended);break;case 'X':result.AddDynamicLevel();break;case 'd':result.SetExclusiveMode(PmapMode.Device);break;case 'q':result.Quiet=true;break;case 'p':result.ShowPath=true;break;case 'k':result.UseKernelName=true;break;case 'r':result.Warnings.Add("option -r is ignored as SunOS compatibility");break;case 'h':result.ShowHelp=true;break;case 'V':result.ShowVersion=true;break;case 'c':result.SetConfigurationMode("c");break;case 'n':result.SetConfigurationMode("n");break;case 'A':case 'C':case 'N':{var attached=optionIndex+1<argument.Length?argument[(optionIndex+1)..]:null;if(!TryTakeValue(args,ref index,attached,out var value)){result.Fail($"option '-{option}' requires an argument");optionIndex=argument.Length;break;}if('A'==option){if(!TryParseRange(value,out result.RangeLow,out result.RangeHigh))result.Fail($"failed to parse argument: '{value}'",false);}else result.SetConfigurationMode(option.ToString());optionIndex=argument.Length;break;}default:result.Fail($"invalid option -- '{option}'");optionIndex=argument.Length;break;}}continue;}operands.Add(argument);}if(result.ShowHelp||result.ShowVersion)return result;if(result.ModeSelections>1)result.Fail("options -c, -C, -d, -n, -N, -x, -X are mutually exclusive",false);foreach(var operand in operands){if(operand.StartsWith("/proc/",StringComparison.Ordinal)){var suffix=operand[6..];if(0==suffix.Length||!char.IsAsciiDigit(suffix[0]))continue;if(TryParsePid(suffix,out var procPid))result.ProcessIds.Add(procPid);else result.Fail($"invalid process id: {operand}");}else if(TryParsePid(operand,out var pid))result.ProcessIds.Add(pid);else result.Fail($"invalid process id: {operand}");}return result;}
	private static bool TryTakeValue(string[] args,ref int index,string? attached,out string? value){if(null!=attached){value=attached;return true;}if(index+1>=args.Length){value=null;return false;}value=args[++index];return true;} private static bool TryParseRange(string? text,out ulong low,out ulong high){low=0;high=ulong.MaxValue;if(null==text)return false;var comma=text.IndexOf(',');if(0>comma){if(!TryParseHex(text,out var address))return false;low=high=address;return true;}if(0<comma&&!TryParseHex(text[..comma],out low))return false;if(comma+1<text.Length&&!TryParseHex(text[(comma+1)..],out high))return false;return 0<=comma&&low<=high;} private static bool TryParseHex(string text,out ulong value){value=0;if(text.StartsWith("0x",StringComparison.OrdinalIgnoreCase))text=text[2..];return 0<text.Length&&ulong.TryParse(text,NumberStyles.AllowHexSpecifier,CultureInfo.InvariantCulture,out value);} private static bool TryParsePid(string text,out int processId){processId=0;if(string.IsNullOrWhiteSpace(text))return false;ulong value;if(text.StartsWith("0x",StringComparison.OrdinalIgnoreCase)){if(!ulong.TryParse(text[2..],NumberStyles.AllowHexSpecifier,CultureInfo.InvariantCulture,out value))return false;}else if(1<text.Length&&'0'==text[0]){value=0;foreach(var character in text){if(character is <'0' or >'7')return false;if(value>(0x7fffffffUL-(ulong)(character-'0'))/8UL)return false;value=value*8UL+(ulong)(character-'0');}}else if(!ulong.TryParse(text,NumberStyles.None,CultureInfo.InvariantCulture,out value))return false;if(0==value||0x7fffffffUL<value)return false;processId=(int)value;return true;}
	private static string NormalizeLineEndings(string value){var normalized=value.Replace("\r\n","\n",StringComparison.Ordinal).Replace("\r","\n",StringComparison.Ordinal);return "\n"==Environment.NewLine?normalized:normalized.Replace("\n",Environment.NewLine,StringComparison.Ordinal);} private static async Task WriteLineAsync(Stream? stream,string text,CancellationToken cancellationToken)=>await WriteAsync(stream,string.Concat(text,Environment.NewLine),cancellationToken).ConfigureAwait(false);private static async Task WriteAsync(Stream? stream,string text,CancellationToken cancellationToken){if(null==stream)return;var bytes=Utf8.GetBytes(text);await stream.WriteAsync(bytes.AsMemory(),cancellationToken).ConfigureAwait(false);}
	private enum PmapMode{Basic,Extended,Device,DynamicExtended}
	private sealed class ParsedArguments{public string? Error;public bool ShowUsageOnError=true;public bool ShowHelp;public bool ShowVersion;public bool Quiet;public bool ShowPath;public bool UseKernelName;public bool ConfigurationMode;public PmapMode Mode;public int DynamicLevel;public int ModeSelections;public ulong RangeLow;public ulong RangeHigh=ulong.MaxValue;public List<int> ProcessIds{get;}=[];public List<string> Warnings{get;}=[];public bool RequiresDetails=>PmapMode.Extended==this.Mode||PmapMode.DynamicExtended==this.Mode;public void SetExclusiveMode(PmapMode mode){if(0==this.ModeSelections){this.ModeSelections=1;this.Mode=mode;return;}if(this.Mode!=mode)this.ModeSelections=2;}public void AddDynamicLevel(){this.DynamicLevel++;this.SetExclusiveMode(PmapMode.DynamicExtended);}public string? ConfigurationKind;public void SetConfigurationMode(string kind){if(null==this.ConfigurationKind){this.ConfigurationKind=kind;this.ModeSelections++;this.ConfigurationMode=true;return;}if(!string.Equals(this.ConfigurationKind,kind,StringComparison.Ordinal))this.ModeSelections=2;}public void Fail(string error,bool showUsage=true){if(null==this.Error){this.Error=error;this.ShowUsageOnError=showUsage;}}}
}
